export default function step({
  phase,
  baseUrl,
  sourceRoom,
  roomName,
  roomAlias,
  room,
  account,
  members,
  previous,
}) {
  const base = baseUrl.replace(/\/+$/, "") + "/_matrix/client/r0",
    enc = encodeURIComponent;
  if (phase === "create")
    return {
      url: base + "/createRoom",
      body: { name: roomName, preset: "public_chat", room_alias_name: roomAlias },
      state: {},
      more: false,
      count: 0,
    };
  if (phase === "who")
    return { url: base + "/account/whoami", body: {}, state: {}, more: false, count: 0 };
  if (phase === "members")
    return {
      url: base + "/rooms/" + enc(sourceRoom) + "/members",
      body: {},
      state: {},
      more: false,
      count: 0,
    };
  if (!room?.room_id || !account?.user_id || !Array.isArray(members?.chunk))
    throw Error("Missing Matrix room, user or members");
  const users = members.chunk
    .map((x) => x.state_key)
    .filter((x) => typeof x === "string" && x && x !== account.user_id);
  const index = previous?.index ?? 0;
  if (phase === "message")
    return {
      url:
        base +
        "/rooms/" +
        enc(room.room_id) +
        "/send/m.room.message/" +
        enc(previous.transaction + "-" + index),
      body: { msgtype: "m.text", body: "Welcome to n8n!" },
      state: previous,
      more: true,
      count: index,
    };
  if (index >= users.length)
    return { url: base, body: {}, state: { index }, more: false, count: index };
  const uid = users[index];
  if (phase === "invite")
    return {
      url: base + "/rooms/" + enc(room.room_id) + "/invite",
      body: { user_id: uid },
      state: {
        index: index + 1,
        transaction:
          previous?.transaction ?? String(Date.now()) + "-" + Math.random().toString(36).slice(2),
      },
      more: true,
      count: index,
    };
  return {
    url:
      base +
      "/rooms/" +
      enc(room.room_id) +
      "/send/m.room.message/" +
      enc(previous.transaction + "-" + index),
    body: { msgtype: "m.text", body: "Welcome to n8n!" },
    state: previous,
    more: true,
    count: index,
  };
}

